// ===== CONFIGURACIÓN =====
const WEBHOOK_SECRET = 'PON_AQUI_TU_SECRETO';   // el MISMO secreto en todos los flujos
// =========================
const q = $input.first().json.query || {};
if (q.t !== WEBHOOK_SECRET) return [{ json: { ok: false } }];
const o = String(q.o || ''), pr = String(q.pr || '');
if (/^GB-[A-Z0-9]{6}$/.test(o)) return [{ json: { ok: true, formula: '{Pedido}="' + o + '"' } }];
if (/^[0-9a-fA-F-]{36}$/.test(pr)) return [{ json: { ok: true, formula: '{PaymentRequestId}="' + pr + '"' } }];
return [{ json: { ok: false } }];

const recs = ($input.first().json.records) || [];
if (!recs.length) return [{ json: { done: true, status: 'PENDIENTE', amount: 0 } }];   // pedido desconocido
const r = recs[0], f = r.fields || {};
if (f['Estado'] === 'PAGADO') return [{ json: { done: true, status: 'PAGADO', amount: Number(f['Monto']) || 0 } }];
if (!f['PaymentRequestId']) return [{ json: { done: true, status: 'PENDIENTE', amount: 0 } }];
return [{ json: { done: false, recordId: r.id, pedido: f['Pedido'], paymentRequestId: f['PaymentRequestId'], monto: Number(f['Monto']) || 0, fields: f } }];

// No se confía en ningún aviso: se compara la respuesta de Clip contra el pedido guardado
const base = $('Decidir').item.json;
const r = $input.first().json || {};
const st = r.status;
if (st === 'CHECKOUT_COMPLETED'
    && Math.abs(Number(r.amount) - Number(base.monto)) < 0.01
    && String((r.metadata || {}).external_reference || '') === String(base.pedido)) {
  return [{ json: { pay: true, recordId: base.recordId, pedido: base.pedido, amount: Number(r.amount), receipt_no: r.receipt_no || '', fields: base.fields, pagadoEn: new Date().toISOString() } }];
}
const failed = (st === 'CHECKOUT_CANCELLED' || st === 'CHECKOUT_EXPIRED');
return [{ json: { pay: false, status: failed ? 'FALLIDO' : 'PENDIENTE', amount: 0 } }];

const f = $('Comparar').item.json.fields || {};
const em = String(f['Correo'] || '').trim().toLowerCase();
const tel = String(f['Teléfono'] || '').replace(/\D/g, '').slice(-10);
return [{ json: { emNorm: em, phNorm: tel ? '52' + tel : '' } }];

// ===== CONFIGURACIÓN META (API de conversiones) =====
const META_PIXEL_ID = '1676702536743834';
const META_CAPI_TOKEN = 'PON_AQUI_TOKEN_META';   // Events Manager > Configuración > API de conversiones > Generar token
const TEST_EVENT_CODE = '';                       // opcional: código de "Probar eventos" para pruebas
// ====================================================
const base = $('Comparar').item.json;
const f = base.fields || {};
if (!META_CAPI_TOKEN || META_CAPI_TOKEN === 'PON_AQUI_TOKEN_META') return [{ json: { skip: true } }];
const user = {};
if ($json.emHash) user.em = [$json.emHash];
if ($json.phHash) user.ph = [$json.phHash];
if (f['fbp']) user.fbp = f['fbp'];
if (f['fbc']) user.fbc = f['fbc'];
const evento = {
  event_name: 'Purchase',
  event_time: Math.floor(Date.now() / 1000),
  event_id: String(base.pedido),                  // mismo id que el navegador => Meta deduplica
  action_source: 'website',
  event_source_url: 'https://gbforce.mx/gracias.html',
  user_data: user,
  custom_data: { currency: 'MXN', value: base.amount, order_id: String(base.pedido), content_name: 'GB FORCE', content_type: 'product', num_items: Number(f['Cantidad']) || 1 }
};
const body = { data: [evento] };
if (TEST_EVENT_CODE) body.test_event_code = TEST_EVENT_CODE;
return [{ json: { skip: false, url: 'https://graph.facebook.com/v19.0/' + META_PIXEL_ID + '/events?access_token=' + encodeURIComponent(META_CAPI_TOKEN), body } }];

// ===== CONFIGURACIÓN DE CORREOS =====
const FROM_EMAIL = 'admin@gbforce.mx';   // ej. admin@gbforce.mx (debe coincidir con la cuenta SMTP)
const TEAM_EMAILS = 'contacto@gbforce.mx';     // uno o varios separados por coma
// ====================================
const base = $('Comparar').item.json;
const f = base.fields || {};
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const cajas = Number(f['Cantidad']) || 1;
const dir = esc(f['Calle']) + ', ' + esc(f['Colonia']) + ', C.P. ' + esc(f['CP']) + ', ' + esc(f['Ciudad']) + ', ' + esc(f['Estado de envío']);
const htmlCliente = '<div style="font-family:Arial,sans-serif;max-width:560px;margin:auto;color:#222">'
  + '<h2 style="margin:0 0 8px">¡Gracias por tu compra, ' + esc(String(f['Nombre'] || '').split(' ')[0]) + '!</h2>'
  + '<p>Recibimos tu pago. Tu número de pedido es <b>' + esc(base.pedido) + '</b>.</p>'
  + '<p><b>Resumen:</b> ' + cajas + (cajas === 1 ? ' caja' : ' cajas') + ' de GB FORCE (7 viales de 10 ml c/u) · Total $' + base.amount + ' MXN.</p>'
  + '<p><b>Enviaremos a:</b><br>' + dir + '</p>'
  + '<p><b>¿Qué sigue?</b> Estamos preparando tu pedido. Cuando salga te mandaremos otro correo con la paquetería y tu número de guía para que sigas tu envío.</p>'
  + '<p style="color:#777;font-size:13px">¿Dudas? Llámanos al +52 33 3172 1515 o escribe a contacto@gbforce.mx.<br>GB FORCE es un suplemento alimenticio; no es un medicamento.</p></div>';
const htmlEquipo = '<div style="font-family:Arial,sans-serif;color:#222"><h3>Nuevo pedido pagado: ' + esc(base.pedido) + '</h3>'
  + '<p><b>' + cajas + (cajas === 1 ? ' caja' : ' cajas') + '</b> · $' + base.amount + ' MXN</p>'
  + '<p><b>' + esc(f['Nombre']) + '</b><br>Tel: ' + esc(f['Teléfono']) + '<br>' + dir + '<br>Referencias: ' + esc(f['Referencias'] || '—') + '</p>'
  + '<p>Prepáralo en la página de envíos.</p></div>';
return [{ json: { fromEmail: FROM_EMAIL, toCliente: f['Correo'] || '', subjCliente: 'Recibimos tu pago · pedido ' + base.pedido, htmlCliente, toEquipo: TEAM_EMAILS, subjEquipo: 'Nuevo pedido pagado ' + base.pedido + ' (' + cajas + (cajas === 1 ? ' caja' : ' cajas') + ')', htmlEquipo } }];
